public class WildcardCopierTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.concurrent.Callable<Object> call) {
        Object actual;
        try {
            actual = call.call();
        } catch (Throwable t) {
            actual = t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    public static void main(String[] args) {
        java.util.List<Number> numbers = new java.util.ArrayList<>();
        check("copyInto(List<Number>, List<Integer>)", 3, WildcardCopier.copyInto(numbers, java.util.List.of(1, 2, 3)));
        check("copyInto(List<Number>, List<Double>)", 1, WildcardCopier.copyInto(numbers, java.util.List.of(4.5)));
        check("sink contents", "[1, 2, 3, 4.5]", numbers.toString());

        java.util.List<Object> anything = new java.util.ArrayList<>();
        WildcardCopier.copyInto(anything, java.util.List.of("x", "y"));
        check("List<Object> accepts strings", "[x, y]", anything.toString());

        check("firstOr on a non-empty List<Double>", 1.5, WildcardCopier.<Number>firstOr(java.util.List.of(1.5, 2.5), 0));
        check("firstOr on an empty list", 99, WildcardCopier.firstOr(new java.util.ArrayList<Integer>(), 99));

        java.util.List<CharSequence> longWords = new java.util.ArrayList<>();
        java.util.function.Predicate<Object> longText = o -> o.toString().length() > 3;
        check("copyMatching count", 2, WildcardCopier.<String>copyMatching(longWords, java.util.List.of("apple", "fig", "kiwi"), longText));
        check("copyMatching contents", "[apple, kiwi]", longWords.toString());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

