import java.util.List;
import java.util.function.Predicate;

public class WildcardCopier {

    public static <T> int copyInto(List<? super T> dest, List<? extends T> src) {
        int copied = 0;
        for (T item : src) {
            dest.add(item);
            copied++;
        }
        return copied;
    }

    public static <T> T firstOr(List<? extends T> src, T fallback) {
        if (src.isEmpty()) {
            return fallback;
        }
        return src.get(0);
    }

    public static <T> int copyMatching(List<? super T> dest, List<? extends T> src, Predicate<? super T> keep) {
        int copied = 0;
        for (T item : src) {
            if (keep.test(item)) {
                dest.add(item);
                copied++;
            }
        }
        return copied;
    }
}
